_52:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n//\n// Simple passthrough fragment shader\n//\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\nvoid main()\n{\n	vec4 pixelColor = v_vColour * texture2D( gm_BaseTexture, v_vTexcoord );\n	pixelColor.a = 0.0;\n	\n// Set any shade of pure green to pure white\n	if (pixelColor.r == pixelColor.b) {\n		if (pixelColor.g - pixelColor.r > 0.1) {\n			pixelColor.rgba = vec4(1.0,1.0,1.0,1.0);\n		}\n	}\n// Set any shade of pure magenta to pure red\n	if (pixelColor.r == pixelColor.b) {\n		if (pixelColor.r - pixelColor.g > 0.1) {\n			pixelColor.rgba = vec4(1.0,0,0,1.0);\n		}\n	}\n// Set colors to pure black if dark enough\n	if (pixelColor.r <= 0.012) {\n		if (pixelColor.g <= 0.012) {\n			if (pixelColor.b <= 0.012) {\n				pixelColor.rgba = vec4(0,0,0,1.0);\n			}\n		}\n	}\n	\n    gl_FragColor = pixelColor;\n}\n",
